func randomBytes(t testing.TB, n int) []byte {
	t.Helper()
	raw := make([]byte, n)
	if _, err := rand.Read(raw); err != nil {
		t.Fatal(err)
	}
	return raw
}

// ordinaryNegatives is what agents read all day that is not a credential, in
// the shapes most likely to be taken for one: lock files with their digests,
// minified JavaScript, CSS classes that begin like a key prefix, digests,
// Kubernetes names, URLs with long opaque segments and inline images. Nothing
// in it may be found by a rule or by the inventory.
func ordinaryNegatives(t testing.TB) map[string]string {
	t.Helper()
	goSum, err := os.ReadFile(filepath.Join("..", "..", "go.sum"))
	if err != nil {
		t.Fatal(err)
	}
	return map[string]string{
		"go.sum":            string(goSum),
		"package-lock.json": packageLock(t),
		"yarn.lock":         yarnLock(t),
		"Cargo.lock":        cargoLock(t),
		"app.min.js":        minifiedJavaScript(t),
		"spinner.css":       prefixLikeCSS(),
		"digests.txt":       digestListing(t),
		"kubectl.txt":       kubernetesNames(t),
		"links.md":          longURLs(t),
		"icons.html":        inlineImages(t),
	}
}

// Package names as registries have them, with the ones that hold a keyword or
// begin like a credential prefix.
var npmPackages = []string{
	"@anthropic-ai/sdk", "@auth0/auth0-react", "@aws-sdk/client-secrets-manager", "@aws-sdk/credential-provider-node", "@aws-sdk/token-providers",
	"@azure/storage-blob", "@babel/core", "@google-cloud/storage", "@huggingface/inference", "@sendgrid/mail", "@sentry/node", "@slack/web-api",
	"@types/jsonwebtoken", "@types/passport-oauth2", "basic-auth", "bcryptjs", "cookie-signature", "csrf", "dotenv", "express-session",
	"hf-loader", "http-proxy-agent", "js-tokens", "jsonwebtoken", "keytar", "node-telegram-bot-api", "npm-run-path", "oauth-sign", "openai",
	"passport-oauth2", "password-prompt", "pypi-info", "safe-buffer", "sk-colors", "sshpk", "stripe", "tweetnacl", "twilio", "uuid", "ws",
}

func npmVersion(t testing.TB) string {
	return randomString(t, "123456789", 1) + "." + randomString(t, decimal, 2) + "." + randomString(t, decimal, 1)
}

func sha512Integrity(t testing.TB) string {
	sum := sha512.Sum512(randomBytes(t, 64))
	return "sha512-" + base64.StdEncoding.EncodeToString(sum[:])
}

func packageLock(t testing.TB) string {
	packages := map[string]any{"": map[string]any{"name": "orders-web", "version": "1.4.2", "license": "MIT",
		"dependencies": map[string]string{"jsonwebtoken": "^9.0.2", "passport-oauth2": "^1.8.0", "stripe": "^16.2.0"}}}
	for _, name := range npmPackages {
		version := npmVersion(t)
		packages["node_modules/"+name] = map[string]any{
			"version":   version,
			"resolved":  "https://registry.npmjs.org/" + name + "/-/" + path.Base(name) + "-" + version + ".tgz",
			"integrity": sha512Integrity(t),
			"license":   "MIT",
			"engines":   map[string]string{"node": ">=14.17"},
			"bin":       map[string]string{path.Base(name) + "-cli": "bin/cli.js"},
			"peerDependencies": map[string]string{
				"@auth0/auth0-spa-js": ">=2.1.0 <3.0.0-beta.1", "typescript": ">=5.4.0",
			},
			"funding": map[string]string{"type": "github", "url": "https://github.com/sponsors/" + path.Base(name)},
		}
	}
	lock, err := json.MarshalIndent(map[string]any{"name": "orders-web", "version": "1.4.2", "lockfileVersion": 3, "requires": true, "packages": packages}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	return string(lock) + "\n"
}

func yarnLock(t testing.TB) string {
	var b strings.Builder
	b.WriteString("# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n# yarn lockfile v1\n\n")
	for _, name := range npmPackages {
		version := npmVersion(t)
		fmt.Fprintf(&b, "%q:\n  version %q\n  resolved \"https://registry.yarnpkg.com/%s/-/%s-%s.tgz#%s\"\n  integrity %s\n  dependencies:\n    js-tokens \"^4.0.0\"\n    safe-buffer \"~5.2.1\"\n\n",
			name+"@^"+version, version, name, path.Base(name), version, randomHex(t, 20), sha512Integrity(t))
	}
	return b.String()
}

func cargoLock(t testing.TB) string {
	var b strings.Builder
	b.WriteString("# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 3\n\n")
	for _, name := range []string{"aes-gcm", "argon2", "aws-credential-types", "aws-sigv4", "base64ct", "hf-hub", "hmac", "jsonwebtoken", "keyring",
		"oauth2", "password-hash", "ring", "rustls-pemfile", "secrecy", "serde_json", "sha2", "subtle", "tokenizers", "tokio", "zeroize"} {
		fmt.Fprintf(&b, "[[package]]\nname = %q\nversion = %q\nsource = \"registry+https://github.com/rust-lang/crates.io-index\"\nchecksum = %q\ndependencies = [\n \"base64ct\",\n \"password-hash\",\n \"subtle\",\n]\n\n",
			name, npmVersion(t), randomHex(t, 32))
	}
	return b.String()
}

// minifiedJavaScript is a bundle as a build writes it: one long line of short
// names, hashed chunk and module ids, subresource digests and an inline source
// map. It holds secret-sounding names, as any login page's code does, with
// nothing secret after them.
func minifiedJavaScript(t testing.TB) string {
	var b strings.Builder
	b.WriteString(`(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4821],{`)
	for i := 0; i < 40; i++ {
		id := randomString(t, "123456789", 1) + randomString(t, decimal, 4)
		fmt.Fprintf(&b, `%s:function(e,t,n){"use strict";n.d(t,{Z:function(){return u}});var r=n(85893),o=n(67294),a=n(%s);function u(e){let{token:t,password:n,onChange:i}=e,[s,c]=(0,o.useState)(null);`, id, randomString(t, decimal, 5))
		b.WriteString(`return(0,r.jsx)("input",{type:"password",autoComplete:"current-password",name:"secret",value:null!=s?s:"",onChange:e=>{c(e.target.value),i(e.target.value)}})}`)
		b.WriteString(`async function l(e,t){let n=await fetch("/api/auth/session",{method:"POST",headers:{Authorization:"Bearer ".concat(e.accessToken),"content-type":"application/json"},body:JSON.stringify({password:t.password,token:t.token})});return n.ok?n.json():null}`)
		fmt.Fprintf(&b, `a.Z.load({src:"/_next/static/chunks/%s-%s.js",integrity:"sha384-%s",crossOrigin:"anonymous"}),`, randomString(t, decimal, 4), randomHex(t, 8), base64.StdEncoding.EncodeToString(randomBytes(t, 48)))
		fmt.Fprintf(&b, `e.exports={buildId:"%s",assetPrefix:"/_next/static/%s",revision:"%s",api_key:process.env.NEXT_PUBLIC_API_KEY,apiKey:r.env.apiKey,auth:null,secret:void 0,password:"",token:t.token||null}},`,
			randomString(t, base64URL, 21), randomString(t, base64URL, 21), randomHex(t, 20))
	}
	b.WriteString(`}]);` + "\n")
	sourceMap, _ := json.Marshal(map[string]any{"version": 3, "file": "4821-" + randomHex(t, 8) + ".js", "sources": []string{"webpack://_N_E/./src/components/LoginForm.tsx", "webpack://_N_E/./src/lib/session.ts"},
		"names": []string{"token", "password", "accessToken", "secret", "useState"}, "mappings": randomString(t, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz,;", 2000)})
	b.WriteString("//# sourceMappingURL=data:application/json;charset=utf-8;base64," + base64.StdEncoding.EncodeToString(sourceMap) + "\n")
	return b.String()
}

// prefixLikeCSS has class names that begin as key prefixes do: SpinKit's sk-
// classes, and others a stylesheet could well hold.
func prefixLikeCSS() string {
	var b strings.Builder
	for _, class := range []string{"sk-spinner", "sk-plane", "sk-chase", "sk-chase-dot", "sk-bounce", "sk-bounce-dot", "sk-wave", "sk-wave-rect", "sk-pulse",
		"sk-flow", "sk-flow-dot", "sk-swing", "sk-swing-dot", "sk-circle", "sk-circle-dot", "sk-circle-fade", "sk-circle-fade-dot", "sk-grid", "sk-grid-cube",
		"sk-fold", "sk-fold-cube", "sk-wander", "sk-wander-cube", "sk-proj-card", "sk-proj-card-title", "sk-ant-menu-item-selected", "sk-or-v1-layout",
		"hf-button", "hf-button--primary", "hf_modal_backdrop", "npm__react-simple-code-editor__textarea", "xapp-header", "xapp-1-sidebar", "dp-pt-selected",
		"shpat_banner", "glpat-notice", "lin_api_docs", "sbp_card", "dapi-table", "whsec_help", "pypi-badge", "SG-icon", "PMAK-row", "AIza-map-container"} {
		fmt.Fprintf(&b, ".%s{display:flex;animation:%s 1.2s infinite ease-in-out}\n.%s:before,.%s>.%s-inner{content:\"\";background-color:var(--%s-color,#333)}\n", class, class, class, class, class, class)
	}
	b.WriteString(".dp.pt.selected{margin:0}.dp.st.active{color:red}.hvs.is-open,.hvb.is-closed{opacity:.6}.SG.icon{width:1em}\n")
	b.WriteString(".css-1a2b3c4-MuiButtonBase-root-MuiButton-root.Mui-focusVisible{outline:0}\n@keyframes sk-chase{100%{transform:rotate(360deg)}}\n")
	return b.String()
}

func digestListing(t testing.TB) string {
	var b strings.Builder
	for i := 0; i < 60; i++ {
		data := randomBytes(t, 64)
		sum256, sum512 := sha256.Sum256(data), sha512.Sum512(data)
		name := fmt.Sprintf("orders-service_1.4.%d_linux_amd64.tar.gz", i)
		fmt.Fprintf(&b, "%s  %s\n", hex.EncodeToString(sum256[:]), name)
		fmt.Fprintf(&b, "SHA512 (%s) = %s\n", name, hex.EncodeToString(sum512[:]))
		fmt.Fprintf(&b, "MD5 (%s) = %s\n", name, randomHex(t, 16))
		fmt.Fprintf(&b, "ghcr.io/acme/orders-service@sha256:%s\n", hex.EncodeToString(sum256[:]))
		fmt.Fprintf(&b, "etag: \"%s\"\nDigest: SHA-256=%s\nContent-MD5: %s\n", randomHex(t, 16), base64.StdEncoding.EncodeToString(sum256[:]), base64.StdEncoding.EncodeToString(randomBytes(t, 16)))
		fmt.Fprintf(&b, "index %s..%s 100644\ncommit %s (HEAD -> main, origin/main)\n", randomHex(t, 4)[:7], randomHex(t, 4)[:7], randomHex(t, 20))
		fmt.Fprintf(&b, "%s refs/heads/main\n.git/objects/pack/pack-%s.pack %s\n", randomHex(t, 20), randomHex(t, 20), strings.ToUpper(randomHex(t, 16)))
	}
	return b.String()
}

// kubernetesNames is what kubectl prints: generated pod and ReplicaSet names,
// Helm release records, the names and types of Secrets (never their data).
func kubernetesNames(t testing.TB) string {
	suffix := func(n int) string { return randomString(t, "bcdfghjklmnpqrstvwxz2456789", n) }
	var b strings.Builder
	b.WriteString("NAME                                          READY   STATUS    RESTARTS   AGE\n")
	for _, name := range []string{"orders-api", "orders-worker", "sk-proj-indexer", "hf-inference-server", "npm-cache", "secret-token-rotator", "dapi-gateway", "dp-st-sync"} {
		for i := 0; i < 5; i++ {
			fmt.Fprintf(&b, "%s-%s-%s                 1/1     Running   0          41d\n", name, suffix(10), suffix(5))
		}
	}
	b.WriteString("\nNAME                                   TYPE                                  DATA   AGE\n")
	for i := 0; i < 20; i++ {
		fmt.Fprintf(&b, "default-token-%s                    kubernetes.io/service-account-token   3      41d\n", suffix(5))
		fmt.Fprintf(&b, "sh.helm.release.v1.orders.v%d           helm.sh/release.v1                    1      %dd\n", i+1, 40-i)
		fmt.Fprintf(&b, "bootstrap-token-%s                    bootstrap.kubernetes.io/token         6      41d\n", suffix(6))
		fmt.Fprintf(&b, "orders-tls                             kubernetes.io/tls                     2      41d\n")
	}
	fmt.Fprintf(&b, `
apiVersion: apps/v1
kind: Deployment
metadata:
  name: orders-api
  uid: %s
  resourceVersion: "%s"
  annotations:
    deployment.kubernetes.io/revision: "7"
    checksum/config: %s
spec:
  template:
    spec:
      serviceAccountName: orders-api
      imagePullSecrets:
      - name: regcred
      containers:
      - name: api
        image: ghcr.io/acme/orders-service@sha256:%s
        envFrom:
        - secretRef:
            name: orders-secrets
        env:
        - name: STRIPE_SECRET_KEY
          valueFrom:
            secretKeyRef:
              name: orders-secrets
              key: stripe-secret-key
        volumeMounts:
        - name: kube-api-access-%s
          mountPath: /var/run/secrets/kubernetes.io/serviceaccount
      volumes:
      - name: kube-api-access-%s
        projected:
          sources:
          - serviceAccountToken:
              expirationSeconds: 3607
              path: token
`, randomUUIDText(t), randomString(t, decimal, 8), randomHex(t, 32), randomHex(t, 32), suffix(5), suffix(5))
	return b.String()
}

func longURLs(t testing.TB) string {
	var b strings.Builder
	for i := 0; i < 30; i++ {
		fmt.Fprintf(&b, "- [design doc](https://docs.google.com/document/d/1%s/edit#heading=h.%s)\n", randomString(t, base64URL, 43), randomString(t, lowerDigits, 12))
		fmt.Fprintf(&b, "- https://github.com/acme/orders-service/blob/%s/src/server.js#L10-L42\n", randomHex(t, 20))
		fmt.Fprintf(&b, "- https://cdn.example.com/assets/index-%s.js and https://cdn.example.com/_next/static/%s/_buildManifest.js\n", randomHex(t, 16), randomString(t, base64URL, 21))
		fmt.Fprintf(&b, "- https://www.figma.com/file/%s/Orders-redesign?node-id=%s%%3A%s\n", randomString(t, alnum, 22), randomString(t, decimal, 4), randomString(t, decimal, 5))
		fmt.Fprintf(&b, "- https://www.notion.so/acme/Runbook-%s and https://youtu.be/%s\n", randomHex(t, 16), randomString(t, base64URL, 11))
		fmt.Fprintf(&b, "- https://registry.npmjs.org/jsonwebtoken/-/jsonwebtoken-9.0.2.tgz and https://hooks.example.com/services/T%s/B%s/%s\n", randomString(t, upperDigits, 10), randomString(t, upperDigits, 10), randomString(t, alnum, 24))
		fmt.Fprintf(&b, "- https://app.example.com/o/%s/projects/%s/issues/%s/events/%s/\n", randomString(t, decimal, 7), randomString(t, decimal, 7), randomString(t, decimal, 10), randomHex(t, 16))
		fmt.Fprintf(&b, "- https://storage.googleapis.com/orders-artifacts/builds/%s/%s/orders-service.tar.gz\n", randomUUIDText(t), randomString(t, base64URL, 64))
		fmt.Fprintf(&b, "- https://api.telegram.org/bots/api#available-methods and https://core.telegram.org/bots/api#%s\n", randomString(t, "abcdefghijklmnopqrstuvwxyz-", 30))
	}
	return b.String()
}

// inlineImages are data URIs short enough to be scanned as text rather than
// skipped as files, in the standard and the URL alphabet.
func inlineImages(t testing.TB) string {
	var b strings.Builder
	for i := 0; i < 12; i++ {
		fmt.Fprintf(&b, "<img alt=\"icon\" src=\"data:image/png;base64,%s\">\n", base64.StdEncoding.EncodeToString(randomBytes(t, 3000)))
		fmt.Fprintf(&b, ".icon-%d{background:url(data:image/webp;base64,%s) no-repeat}\n", i, base64.StdEncoding.EncodeToString(randomBytes(t, 1500)))
		fmt.Fprintf(&b, "![chart](data:image/gif;base64,%s)\n", base64.RawURLEncoding.EncodeToString(randomBytes(t, 2000)))
	}
	return b.String()
}
